225	const lookUpShop = async (config: E2eConfig, token: string) => {
226	  const data = await gql<{
227	    channel: { id: string };
228	    categories: { edges: { node: { id: string } }[] };
229	    promotions: { edges: { node: { id: string } }[] };
230	    warehouses: {
231	      edges: {
232	        node: {
233	          id: string;
234	          shippingZones: {
235	            edges: { node: { countries: { code: string }[]; channels: { slug: string }[] } }[];
236	          };
237	        };
238	      }[];
239	    };
240	  }>(
241	    config,
242	    `query($channel: String!) {
243	      channel(slug: $channel) { id }
244	      categories(first: 1) { edges { node { id } } }
245	      promotions(first: 100) { edges { node { id } } }
246	      warehouses(first: 100) {
247	        edges { node { id shippingZones(first: 100) { edges { node { countries { code } channels { slug } } } } } }
248	      }
249	    }`,
